import AxeBuilder from "@axe-core/playwright";
import { test, expect } from "../helpers/theme-browser";
import { Pool } from "pg";
import { randomUUID } from "node:crypto";

const pool = new Pool({ connectionString: process.env.DATABASE_URL });
test.skip(
  process.env.MAILLOOP_E2E_ISOLATED !== "1",
  "Use the disposable database runner.",
);
test.afterAll(() => pool.end());

async function seed(userId: string) {
  const id = randomUUID();
  await pool.query(
    `INSERT INTO "Template" (id,"userId",name,subject,body) VALUES ($1,$2,'Editor fixture','Hello {{name}}','Hi {{name}},\n\n**Welcome**\n- {{company}}\n1. {{role}}')`,
    [id, userId],
  );
  await pool.query(
    `INSERT INTO "Contact" (id,"userId",name,email,company,"jobRole") VALUES ($1,$2,'Alex Morgan','[REDACTED_EMAIL]','Example Co','Engineer')`,
    [randomUUID(), userId],
  );
  await pool.query(
    `INSERT INTO "Contact" (id,"userId",name,email,company,"jobRole") VALUES ($1,$2,'Zoe','[REDACTED_EMAIL]',NULL,'Designer')`,
    [randomUUID(), userId],
  );
  return id;
}

const themes = [
  "Lavender Light",
  "Nightbloom Dark",
  "Chalk Light",
  "Obsidian Dark",
];
test("editor layout across themes and widths", async ({
  page,
  themeUser,
}, testInfo) => {
  const id = await seed(themeUser);
  await page.goto(`/templates?edit=${id}`);
  expect(
    (
      await new AxeBuilder({ page })
        .include(".template-editor")
        .withRules(["aria-allowed-role"])
        .analyze()
    ).violations,
  ).toEqual([]);
  for (const width of [1440, 1024, 390]) {
    await page.setViewportSize({ width, height: 900 });
    for (const theme of themes) {
      await page.getByRole("button", { name: "Choose appearance" }).click();
      await page
        .getByRole("menuitemradio", { name: theme, exact: true })
        .click();
      await expect(
        page.getByLabel("Template name", { exact: true }),
      ).toBeVisible();
      const textarea = page.getByLabel("Message", { exact: true });
      expect(
        Math.round((await textarea.boundingBox())!.height),
      ).toBeGreaterThanOrEqual(460);
      expect(
        await page.evaluate(
          () => document.documentElement.scrollWidth <= innerWidth,
        ),
      ).toBe(true);
      await expect(
        page.getByRole("button", { name: "Save template", exact: true }),
      ).toBeEnabled();
      await page
        .getByRole("button", { name: "Formatting tips", exact: true })
        .click();
      await expect(
        page.getByRole("button", { name: "Hide tips" }),
      ).toHaveAttribute("aria-expanded", "true");
      await page.getByLabel("Template name", { exact: true }).fill("");
      await expect(
        page.getByRole("button", { name: "Save template", exact: true }),
      ).toBeDisabled();
      await page.evaluate(() => window.scrollTo(0, 0));
      await page.screenshot({
        path: testInfo.outputPath(`${width}-${theme}-write.png`),
        fullPage: true,
      });
      await page
        .getByLabel("Template name", { exact: true })
        .fill("Editor fixture");
      await page.getByRole("button", { name: "Hide tips" }).click();
      if (width < 960)
        await page.getByRole("tab", { name: "Preview", exact: true }).click();
      await expect(
        page.getByLabel("Preview as", { exact: true }),
      ).toBeVisible();
      const preview = page.locator(".template-editor-preview");
      await expect(preview).toHaveCSS(
        "position",
        width < 960 ? "static" : "sticky",
      );
      await expect(page.locator(".mail-preview-body strong")).toHaveText(
        "Welcome",
      );
      await expect(page.locator(".mail-preview-body ul li")).toHaveText(
        "Example Co",
      );
      await expect(page.locator(".mail-preview-body ol li")).toHaveText(
        "Engineer",
      );
      await page.evaluate(() => window.scrollTo(0, 0));
      await page.screenshot({
        path: testInfo.outputPath(`${width}-${theme}-preview.png`),
        fullPage: true,
      });
      if (width < 960)
        await page.getByRole("tab", { name: "Write", exact: true }).click();
    }
  }
});

test("insertion, validation, scrolling and mobile saving", async ({
  page,
  themeUser,
}) => {
  const id = await seed(themeUser);
  await page.setViewportSize({ width: 1024, height: 900 });
  await page.goto(`/templates?edit=${id}`);
  const subject = page.getByLabel("Subject", { exact: true });
  const body = page.getByLabel("Message", { exact: true });
  const save = page.getByRole("button", { name: "Save template", exact: true });
  await page
    .getByLabel("Preview as", { exact: true })
    .selectOption({ label: "Zoe · Designer" });
  await expect(
    page.getByText(
      "Missing values: company. These placeholders resolve to empty text.",
      { exact: true },
    ),
  ).toBeVisible();
  await page
    .getByLabel("Preview as", { exact: true })
    .selectOption({ label: "Alex Morgan · Example Co · Engineer" });
  await subject.fill("Hello replace");
  await subject.evaluate((el: HTMLInputElement) => el.setSelectionRange(6, 13));
  await page.getByRole("button", { name: "{{company}}", exact: true }).click();
  await expect(subject).toHaveValue("Hello {{company}}");
  await expect(subject).toBeFocused();
  await body.fill("Hello ");
  await body.press("End");
  await page.getByRole("button", { name: "{{name}}", exact: true }).focus();
  await page.keyboard.press("Enter");
  await expect(body).toHaveValue("Hello {{name}}");
  await expect(page.getByText("2 words", { exact: true })).toBeVisible();
  for (const value of ["{{nme}}", "{{name", "}}", "   "]) {
    await body.fill(value);
    await expect(save).toBeDisabled();
  }
  await body.fill(
    Array.from({ length: 100 }, (_, i) => `Line ${i} {{name}}`).join("\n"),
  );
  await expect(save).toBeEnabled();
  await body.evaluate((el) => {
    el.style.height = "1000px";
  });
  await page.evaluate(() => window.scrollTo(0, 500));
  await expect
    .poll(async () =>
      Math.round(
        (await page.locator(".template-editor-preview").boundingBox())!.y,
      ),
    )
    .toBe(16);
  const header = page.locator(".mail-preview > div").first();
  const before = await header.boundingBox();
  await page.locator(".mail-preview-body").evaluate((el) => {
    el.scrollTop = 400;
  });
  expect((await header.boundingBox())!.y).toBe(before!.y);
  expect(
    await page.locator(".mail-preview-body").evaluate((el) => el.scrollTop),
  ).toBeGreaterThan(0);
  await page.setViewportSize({ width: 390, height: 844 });
  await page.getByRole("tab", { name: "Write", exact: true }).focus();
  await page.keyboard.press("ArrowRight");
  await expect(
    page.getByRole("tab", { name: "Preview", exact: true }),
  ).toHaveAttribute("aria-selected", "true");
  await expect(body).toBeHidden();
  await expect(save).toBeVisible();
  await save.click();
  await expect(
    page
      .getByTestId("success-toast")
      .getByText("Template saved successfully.", { exact: true }),
  ).toBeVisible();
  await expect(page).toHaveURL(/\/templates$/);
  await expect(page.locator(".template-editor-page")).toHaveCount(0);
  const stored = await pool.query(
    'SELECT subject,body FROM "Template" WHERE id=$1 AND "userId"=$2',
    [id, themeUser],
  );
  expect(stored.rows[0].subject).toBe("Hello {{company}}");
  expect(stored.rows[0].body).toContain("Line 99 {{name}}");
});

test("new template retains sample preview, example, save and cancel behavior", async ({
  page,
  themeUser,
}) => {
  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto("/templates?new=1");
  const save = page.getByRole("button", { name: "Save template", exact: true });
  await expect(save).toBeDisabled();
  await page.getByRole("button", { name: "Use Example", exact: true }).click();
  await page.getByLabel("Template name", { exact: true }).fill("New example");
  await page.getByRole("tab", { name: "Preview", exact: true }).click();
  await expect(page.getByLabel("Preview as", { exact: true })).toBeDisabled();
  await expect(
    page.getByText("Sample values shown.", { exact: false }),
  ).toBeVisible();
  await save.click();
  await expect(
    page
      .getByTestId("success-toast")
      .getByText("Template saved successfully.", { exact: true }),
  ).toBeVisible();
  const saved = await pool.query(
    'SELECT name FROM "Template" WHERE "userId"=$1',
    [themeUser],
  );
  expect(saved.rows.map((row) => row.name)).toEqual(["New example"]);
  await page.getByRole("tab", { name: "Write", exact: true }).click();
  await expect(page.getByLabel("Template name", { exact: true })).toHaveValue(
    "",
  );
  await page.getByLabel("Template name", { exact: true }).fill("Unsaved");
  page.once("dialog", (dialog) => dialog.dismiss());
  await page.getByRole("link", { name: "Cancel", exact: true }).click();
  await expect(page.getByLabel("Template name", { exact: true })).toHaveValue(
    "Unsaved",
  );
  page.once("dialog", (dialog) => dialog.accept());
  await page.getByRole("link", { name: "Cancel", exact: true }).click();
  await expect(page).toHaveURL(/\/templates$/);
  await expect(page.locator(".template-editor-page")).toHaveCount(0);
});

test("line break insertion preserves the message cursor, preview and saved text", async ({
  page,
  themeUser,
}) => {
  const id = await seed(themeUser);
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto(`/templates?edit=${id}`);
  await page
    .getByRole("button", { name: "Formatting tips", exact: true })
    .click();
  await expect(page.getByRole("button", { name: "Hide tips" })).toHaveAttribute(
    "aria-expanded",
    "true",
  );
  const body = page.getByLabel("Message", { exact: true });
  const button = page.getByRole("button", { name: "Line break", exact: true });
  for (const [start, end, expected] of [
    [0, 0, "\nHello world"],
    [5, 5, "Hello\n world"],
    [11, 11, "Hello world\n"],
    [5, 11, "Hello\n"],
  ] as const) {
    await body.fill("Hello world");
    await body.press("Home");
    for (let index = 0; index < start; index++) await body.press("ArrowRight");
    for (let index = start; index < end; index++)
      await body.press("Shift+ArrowRight");
    // A subject focus change must not redirect a message-only line break.
    await page.getByLabel("Subject", { exact: true }).focus();
    await button.click();
    await expect(body).toHaveValue(expected);
    await expect(body).toBeFocused();
    expect(
      await body.evaluate((el: HTMLTextAreaElement) => el.selectionStart),
    ).toBe(start + 1);
    await expect(page.locator(".mail-message-content")).toHaveText(expected);
  }
  await body.fill("Hello world");
  await body.press("End");
  await button.focus();
  await page.keyboard.press("Enter");
  await button.focus();
  await page.keyboard.press("Enter");
  await body.pressSequentially("Next paragraph");
  await expect(body).toHaveValue("Hello world\n\nNext paragraph");
  await page
    .getByRole("button", { name: "Save template", exact: true })
    .click();
  await expect(page.getByTestId("success-toast")).toBeVisible();
  await page.goto(`/templates?edit=${id}`);
  await expect(body).toHaveValue("Hello world\n\nNext paragraph");
});

test("message previews use email typography and fit desktop and mobile widths", async ({
  page,
  themeUser,
}) => {
  const id = await seed(themeUser);
  await page.goto(`/templates?edit=${id}`);
  await page
    .getByRole("button", { name: "Formatting tips", exact: true })
    .click();
  await expect(page.getByRole("button", { name: "Hide tips" })).toHaveAttribute(
    "aria-expanded",
    "true",
  );
  const text = `Hi {{name}},\n\n${"A long personalized paragraph for {{company}}. ".repeat(20)}\nhttps://example.test/${"long-path".repeat(50)}\n\n- First item\n- **Second item**\n\n1. {{role}}`;
  await page.getByLabel("Message", { exact: true }).fill(text);
  await page
    .getByRole("button", { name: "Save template", exact: true })
    .click();
  await expect(page.getByTestId("success-toast")).toBeVisible();
  for (const route of [`/templates?edit=${id}`, "/compose"]) {
    for (const width of [1440, 390]) {
      await page.setViewportSize({ width, height: 900 });
      await page.goto(route);
      if (route === "/compose") {
        await page
          .getByLabel("Choose a template", { exact: true })
          .selectOption(id);
        await page.getByRole("checkbox").first().check();
      } else if (width < 960) {
        await page.getByRole("tab", { name: "Preview", exact: true }).click();
      }
      const content = page.locator(".mail-message-content");
      await expect(content).toBeVisible();
      await expect(content).toHaveCSS("max-width", "640px");
      await expect(content).toHaveCSS("font-size", "14px");
      await expect(content).toHaveCSS("line-height", "21px");
      await expect(content.locator("ul li")).toHaveText([
        "First item",
        "Second item",
      ]);
      await expect(content.locator("ol li")).toHaveText("Engineer");
      expect(
        await content.evaluate((el) => el.scrollWidth <= el.clientWidth),
      ).toBe(true);
      expect((await content.boundingBox())!.width).toBeLessThanOrEqual(640);
      expect(
        await page.evaluate(
          () => document.documentElement.scrollWidth <= innerWidth,
        ),
      ).toBe(true);
    }
  }
});
